  <style>
    :root {
      color-scheme: dark;
      --bg: #0b1020;
      --panel: rgba(18, 24, 45, 0.88);
      --panel-border: rgba(148, 163, 184, 0.18);
      --text: #e5eefb;
      --muted: #99a6c5;
      --accent: #7c9cff;
      --accent-strong: #97b0ff;
      --accent-soft: rgba(124, 156, 255, 0.16);
      --success: #7ee0b5;
      --shadow: 0 24px 60px rgba(0, 0, 0, 0.45);
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      font-family: Arial, Helvetica, sans-serif;
      background:
        radial-gradient(circle at top, rgba(124, 156, 255, 0.18), transparent 34%),
        linear-gradient(180deg, #0f172a 0%, #0b1020 100%);
      color: var(--text);
      display: grid;
      place-items: center;
      padding: 32px 18px;
    }

    .quiz-card {
      width: min(100%, 760px);
      background: var(--panel);
      border: 1px solid var(--panel-border);
      border-radius: 24px;
      box-shadow: var(--shadow);
      padding: 32px;
      backdrop-filter: blur(18px);
    }

    h1 {
      margin: 0 0 10px;
      font-size: clamp(1.9rem, 4vw, 2.5rem);
    }

    .intro {
      margin: 0 0 28px;
      color: var(--muted);
      line-height: 1.6;
    }

    form {
      display: grid;
      gap: 20px;
    }

    .form-field {
      background: rgba(15, 23, 42, 0.78);
      border: 1px solid rgba(148, 163, 184, 0.14);
      border-radius: 18px;
      padding: 22px 20px;
    }

    .question-number {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      min-width: 34px;
      height: 34px;
      border-radius: 999px;
      background: var(--accent-soft);
      color: var(--accent-strong);
      font-weight: 700;
      margin-bottom: 14px;
    }

    .question-title {
      margin: 0 0 8px;
      font-size: 1.1rem;
      line-height: 1.5;
    }

    .help-text {
      margin: 0 0 16px;
      color: var(--muted);
      font-size: 0.95rem;
    }

    .choices {
      display: grid;
      gap: 12px;
    }

    .choice {
      display: flex;
      align-items: center;
      gap: 12px;
      padding: 14px 16px;
      background: rgba(30, 41, 59, 0.65);
      border: 1px solid transparent;
      border-radius: 14px;
      transition: border-color 0.2s ease, background 0.2s ease, transform 0.2s ease;
      cursor: pointer;
    }

    .choice:hover {
      border-color: rgba(124, 156, 255, 0.45);
      background: rgba(39, 53, 78, 0.8);
      transform: translateY(-1px);
    }

    .choice input {
      width: 18px;
      height: 18px;
      accent-color: var(--accent);
      margin: 0;
      flex: 0 0 auto;
    }

    .choice span {
      line-height: 1.4;
    }

    button {
      border: 0;
      border-radius: 14px;
      padding: 15px 20px;
      font-size: 1rem;
      font-weight: 700;
      color: #08111f;
      background: linear-gradient(135deg, var(--accent-strong), #c4d2ff);
      cursor: pointer;
      transition: transform 0.2s ease, box-shadow 0.2s ease;
      box-shadow: 0 14px 28px rgba(124, 156, 255, 0.28);
    }

    button:hover {
      transform: translateY(-1px);
      box-shadow: 0 18px 34px rgba(124, 156, 255, 0.34);
    }

    #result {
      margin-top: 22px;
      padding: 18px 20px;
      border-radius: 16px;
      background: rgba(16, 185, 129, 0.12);
      border: 1px solid rgba(126, 224, 181, 0.22);
      color: var(--success);
      line-height: 1.6;
      display: none;
    }

    #result strong {
      color: #dff8ed;
    }

    @media (max-width: 640px) {
      .quiz-card {
        padding: 24px 18px;
      }

      .form-field {
        padding: 18px 16px;
      }
    }
  </style>
</head>
<body>
  <main class="quiz-card">
    <h1>Computer Languages Quiz</h1>
    <p class="intro">Pick as many answers as you think fit each question, then submit to review your selections.</p>

    <form id="quiz-form">
      <div class="form-field">
        <div class="question-number">1</div>
        <h2 class="question-title">Which of these are commonly used for web development?</h2>
        <p class="help-text">Tip: more than one choice may be correct, so check every option that applies.</p>
        <div class="choices">
          <label class="choice"><input type="checkbox" name="q1" value="JavaScript"><span>JavaScript</span></label>
          <label class="choice"><input type="checkbox" name="q1" value="HTML"><span>HTML</span></label>
          <label class="choice"><input type="checkbox" name="q1" value="Python"><span>Python</span></label>
          <label class="choice"><input type="checkbox" name="q1" value="CSS"><span>CSS</span></label>
        </div>
      </div>

      <div class="form-field">
        <div class="question-number">2</div>
        <h2 class="question-title">Which languages are known for systems programming?</h2>
        <div class="choices">
          <label class="choice"><input type="checkbox" name="q2" value="C"><span>C</span></label>
          <label class="choice"><input type="checkbox" name="q2" value="Rust"><span>Rust</span></label>
          <label class="choice"><input type="checkbox" name="q2" value="Go"><span>Go</span></label>
          <label class="choice"><input type="checkbox" name="q2" value="SQL"><span>SQL</span></label>
        </div>
      </div>

      <div class="form-field">
        <div class="question-number">3</div>
        <h2 class="question-title">Which of these are primarily used to query or structure data?</h2>
        <div class="choices">
          <label class="choice"><input type="checkbox" name="q3" value="SQL"><span>SQL</span></label>
          <label class="choice"><input type="checkbox" name="q3" value="XML"><span>XML</span></label>
          <label class="choice"><input type="checkbox" name="q3" value="Java"><span>Java</span></label>
          <label class="choice"><input type="checkbox" name="q3" value="JSON"><span>JSON</span></label>
        </div>
      </div>

      <button type="submit">Submit Quiz</button>
    </form>

    <div id="result" aria-live="polite"></div>
  </main>

  <script>
    const form = document.getElementById("quiz-form");
    const result = document.getElementById("result");
    const questions = [
      { name: "q1", label: "Question 1" },
      { name: "q2", label: "Question 2" },
      { name: "q3", label: "Question 3" }
    ];

    form.addEventListener("submit", function (event) {
      event.preventDefault();

      const summary = questions.map(function (question) {
        const selected = Array.from(
          form.querySelectorAll('input[name="' + question.name + '"]:checked')
        ).map(function (input) {
          return input.value;
        });

        return "<strong>" + question.label + ":</strong> " + (selected.length ? selected.join(", ") : "No choices selected");
      });

      result.innerHTML = summary.join("<br>");
      result.style.display = "block";
    });
  </script>
</body>
</html>
